USE `three_kingdoms_life`;

INSERT INTO `tb_three_kingdoms_events_catalog` (
  `id`, `category`, `priority`, `campaign_name`,
  `min_year`, `max_year`, `seasons_json`, `min_age`, `max_age`,
  `required_camp`, `required_provinces_json`, `required_flags_json`, `forbidden_flags_json`, `min_stats_json`,
  `historical_figure_id`, `narrative_template`, `dialogue_prompt`, `dialogue_quote`,
  `choices_json`, `is_enabled`
) VALUES
  ('evt_infant_184_spring', 'INFANT_SURVIVAL', 95, NULL, 184, 184, '[0]', 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, '公元184年孟春正月，你在【{郡名}·{县名}】一间破瓦草屋中呱呱坠地。父亲{父名}在门首插了一根柳枝驱邪，母亲{母名}虚弱地给你喂了一口温米汤。外头春寒未散，冰凌滴水，你来到这个人世间了。', NULL, NULL, '[]', 1),
  ('evt_infant_184_snow_blessing', 'INFANT_SURVIVAL', 95, NULL, 184, 184, '[0]', 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, '中平元年孟春，一场厚达数寸的早春瑞雪铺满【{郡名}】原野。你伴着窗外怒放的红梅啼哭降生。父亲{父名}抖落蓑衣上的雪花，双手合十祈愿：“瑞雪兆丰年，愿这孩子在乱世里平平安安长大。”', NULL, NULL, '[]', 1),
  ('evt_infant_184_boat_cradle', 'INFANT_SURVIVAL', 95, NULL, 184, 184, '[0]', 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, '江水初融，波光粼粼。你在【{郡名}】江畔一条摇曳的乌篷小渔舟上降生。母亲{母名}将你安置在柔韧的芦苇摇篮里，枕着拍打船舷的春水与两岸水鸟清啼，开启了你的人间旅程。', NULL, NULL, '[]', 1),
  ('evt_infant_184_turbans_flee', 'INFANT_SURVIVAL', 95, NULL, 184, 184, '[0]', 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, '初春大乱，黄巾裹挟万众席卷郡县。村外火把森森、锣鼓喧天，全家人躲在地窖暗处屏息凝神，你在父亲{父名}温暖宽厚的手掌庇护下轻声坠地，在最深沉的恐惧中为全家带来了唯一的新生希望。', NULL, NULL, '[]', 1),
  ('evt_infant_184_summer', 'INFANT_SURVIVAL', 95, NULL, 184, 184, '[1]', 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, '四月入夏，天气转热。母亲{母名}抱着你坐在槐树荫下纳凉赶蚊。隔壁村子传来黄巾余党打劫大户的喧闹声，父亲把门板用粗木死死顶住。', NULL, NULL, '[]', 1),
  ('evt_infant_184_summer_breeze', 'INFANT_SURVIVAL', 95, NULL, 184, 184, '[1]', 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, '初夏溽热，院落中老槐树绿荫如盖。母亲{母名}摇着一把蒲草扇轻摇摇篮，在青砖旁燃起一把晒干的艾草驱逐蚊蚋。你在温和的青草药香中安然吮指酣睡。', NULL, NULL, '[]', 1),
  ('evt_infant_184_autumn', 'INFANT_SURVIVAL', 95, NULL, 184, 184, '[2]', 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, '秋风初起，高粱熟了。村里被官府抽走两人去广宗前线推车运粮，母亲把你背在后背上在麦场拾麦穗，你睁着大眼睛咿呀学语。', NULL, NULL, '[]', 1),
  ('evt_infant_184_autumn_granary', 'INFANT_SURVIVAL', 95, NULL, 184, 184, '[2]', 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, '金风送爽，村东打谷场上连枷翻飞，尘麦泛黄。父亲{父名}满身汗水挑回两袋新打下的红粟米，祖母盛出一碗熬得浓稠黏香的米油，轻轻点在你的唇角，你吧唧着小嘴欢快笑出声来。', NULL, NULL, '[]', 1),
  ('evt_infant_184_winter', 'INFANT_SURVIVAL', 95, NULL, 184, 184, '[3]', 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, '冬雪纷飞，你度过了人生的第一个年关。天寒地冻，柴炭稀缺，父亲在土灶里烧野草给你烘热襁褓，全家人紧挨在一起取暖。', NULL, NULL, '[]', 1),
  ('evt_infant_184_winter_solstice', 'INFANT_SURVIVAL', 95, NULL, 184, 184, '[3]', 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, '冬至大如年，乡里杀猪宰羊祭祖。里正分给各家一升骨汤，母亲{母名}用布巾蘸热汤为你揉擦冻红的脚趾与耳朵。窗外北风呼号，全家在暖融融的土炕上平安迎来了新岁。', NULL, NULL, '[]', 1),
  ('evt_toddler_1_zhuazhou', 'INFANT_SURVIVAL', 90, NULL, 185, 185, '[0,1]', 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, '公元185年中平二年，你满周岁了！按汉家习俗，父母在红漆案几上设下“晬盘”，陈列各色物件。长辈笑吟吟地将你放在桌前，看你稚嫩的小手抓向何方。', '周岁试儿，红案上琳琅满目，你牙牙学语爬上前去，一把抓住了什么？', NULL, '[{\"id\":\"c_zhuazhou_abacus\",\"label\":\"【算盘铜钱】：伸出肉乎乎的小手紧紧攥住算盘与小铜钱串\",\"description\":\"天生对财货数目敏锐，具有经商立命的敏慧天赋。\",\"approachTag\":\"【商贾敏慧】\",\"requirementHint\":\"理财生慧，家资丰隆\",\"statChanges\":{\"wealth\":6,\"intellect\":4},\"outcomeText\":\"你握着铜钱叮当脆响咯咯大笑，长辈喜道：“这孩子日后必是个通晓度支、生财有道的陶朱之才！”\",\"eventFlagToSet\":\"done:evt_toddler_1_zhuazhou\"},{\"id\":\"c_zhuazhou_wooden_sword\",\"label\":\"【桃木小剑】：径直爬向案头，一把抱住桃木雕刻的玩具短剑与红缨小矛\",\"description\":\"自幼慕勇尚武，眉宇间有一股不服输的英武胆魄。\",\"approachTag\":\"【崇武英气】\",\"requirementHint\":\"强筋健骨，勇毅萌芽\",\"statChanges\":{\"martial\":6,\"health\":4},\"outcomeText\":\"舅父拍案喝彩：“此子眉带英骨，手握兵戈，将来定是一员破阵先锋的大将之材！”\",\"eventFlagToSet\":\"done:evt_toddler_1_zhuazhou\"},{\"id\":\"c_zhuazhou_classics_scroll\",\"label\":\"【论语竹简】：撇开金银玩具，小手一把抱住墨香犹存的《论语》竹简\",\"description\":\"生而好学，亲近文墨典籍，宿慧天然。\",\"approachTag\":\"【文华宿慧】\",\"requirementHint\":\"诗书滋养，明晓是非\",\"statChanges\":{\"intellect\":8,\"virtue\":4},\"outcomeText\":\"路过的老塾师抚须微笑：“稚子不慕金玉而好典册，宿慧天成，日后或可博览经史，步入仕途！”\",\"eventFlagToSet\":\"done:evt_toddler_1_zhuazhou\"},{\"id\":\"c_zhuazhou_clay_plow\",\"label\":\"【陶泥耕犁】：抱住陶泥捏成的小水牛与木犁玩得满脸泥土，憨态可掬\",\"description\":\"亲近大地泥土，忠厚质朴，本分知足。\",\"approachTag\":\"【敦厚本分】\",\"requirementHint\":\"厚德载物，身骨康健\",\"statChanges\":{\"virtue\":6,\"health\":6,\"fortune\":4},\"outcomeText\":\"祖父抚摸着你的小脑袋欣慰道：“知农家穑事之艰辛，勤劳厚实，定能福泽延绵、安乐一生！”\",\"eventFlagToSet\":\"done:evt_toddler_1_zhuazhou\"}]', 1),
  ('evt_toddler_1_first_steps', 'INFANT_SURVIVAL', 80, NULL, 185, 185, '[2,3]', 1, 1, NULL, NULL, NULL, NULL, NULL, NULL, '深秋阳光晒得土院暖洋洋的。你扶着斑驳的泥墙，晃晃悠悠迈开了人生最初的几个独立步伐。', '你摇晃着小身板在院中迈步，突然身子一歪要摔倒，你作何反应？', NULL, '[{\"id\":\"c_step_laugh\",\"label\":\"摔倒在软草堆里非但不哭，反而咯咯大笑翻身爬起继续冲\",\"description\":\"生性皮实乐观，不怕跌倒。\",\"approachTag\":\"【坚韧无畏】\",\"requirementHint\":\"体魄强健，勇往直前\",\"statChanges\":{\"health\":6,\"martial\":2},\"outcomeText\":\"母亲在旁看得心疼又好笑，抱起你揉了揉膝盖，你欢快地在草地上奔跑打转。\",\"eventFlagToSet\":\"done:evt_toddler_1_first_steps\"},{\"id\":\"c_step_share_fruit\",\"label\":\"稳住身形捡起地上一枚熟透红枣，踉跄跑去塞进母亲手心\",\"description\":\"天性孝顺体贴，懂得关爱至亲。\",\"approachTag\":\"【至纯纯孝】\",\"requirementHint\":\"纯孝仁厚，福泽自生\",\"statChanges\":{\"virtue\":6,\"fortune\":4},\"outcomeText\":\"母亲红着眼眶将你搂在怀里亲了一口，直夸你是全家人的贴心小宝贝。\",\"eventFlagToSet\":\"done:evt_toddler_1_first_steps\"},{\"id\":\"c_step_observe_birds\",\"label\":\"扶着门槛站定，静静盯着屋檐下燕子筑巢呢喃，久久不愿离去\",\"description\":\"生来心细专注，具有超乎常人的观察力。\",\"approachTag\":\"【敏锐察物】\",\"requirementHint\":\"启迪悟性，增长识见\",\"statChanges\":{\"intellect\":6,\"virtue\":2},\"outcomeText\":\"小小年纪便有凝神专注之气象，邻人皆赞你眼神清澈有灵光。\",\"eventFlagToSet\":\"done:evt_toddler_1_first_steps\"}]', 1),
  ('evt_toddler_2_village_nuo', 'INFANT_SURVIVAL', 85, NULL, 186, 186, '[0]', 2, 2, NULL, NULL, NULL, NULL, NULL, NULL, '两岁春，村中举行汉代古俗“大傩之祭”。傩师戴着青面獠牙的木雕面具，执戈扬盾呼喝踏罡，锣鼓喧天。', '面目狰狞的傩师跳跃穿行于街巷，众小儿惊骇啼哭，你作何反应？', NULL, '[{\"id\":\"c_nuo_courage\",\"label\":\"伸出小手去摸狰狞的傩神木面具，非但不怕还拍手喝彩\",\"description\":\"天生胆大包天，煞气不侵。\",\"approachTag\":\"【胆识过人】\",\"requirementHint\":\"勇略天生，胆气壮硕\",\"statChanges\":{\"martial\":4,\"health\":4},\"outcomeText\":\"傩师驻足大笑，取下一枚压胜红绳系在你的手腕上，保你百病不侵。\",\"eventFlagToSet\":\"done:evt_toddler_2_village_nuo\"},{\"id\":\"c_nuo_hide\",\"label\":\"一头钻进母亲衣襟下，透过手指缝隙偷偷观察傩师步伐与铜锣法器\",\"description\":\"生性谨慎机敏，懂得保护自己又暗中观察。\",\"approachTag\":\"【审慎机警】\",\"requirementHint\":\"识见通达，趋利避害\",\"statChanges\":{\"intellect\":4,\"fortune\":4},\"outcomeText\":\"你默默记住了傩戏节奏与神辞，回到家中拿起树枝有模有样模仿舞动，众人大奇。\",\"eventFlagToSet\":\"done:evt_toddler_2_village_nuo\"},{\"id\":\"c_nuo_comfort_peer\",\"label\":\"捡起傩师洒下的红枣和炒豆，塞给身边被鼓声吓哭了的邻家小女童\",\"description\":\"心地仁厚温善，小小年纪已懂得照拂弱小。\",\"approachTag\":\"【敦厚友爱】\",\"requirementHint\":\"仁厚宽和，广结善缘\",\"statChanges\":{\"virtue\":6,\"intellect\":2},\"outcomeText\":\"女童破涕为笑，邻庄大娘连连夸赞你是个知冷知热的仁厚好苗子。\",\"eventFlagToSet\":\"done:evt_toddler_2_village_nuo\"}]', 1),
  ('evt_toddler_2_chasing_geese', 'INFANT_SURVIVAL', 75, NULL, 186, 186, '[1]', 2, 2, NULL, NULL, NULL, NULL, NULL, NULL, '两岁夏日，山溪潺潺。几只大白鹅昂首挺胸在溪滩游荡，扇动雪白双翅，声势吓人。', '领头的大白鹅伸长脖子扑腾过来，你打算如何应对？', NULL, '[{\"id\":\"c_geese_fight\",\"label\":\"抓起一根折断的柳枝威风凛凛地挥舞，将大白鹅喝退扑腾入水\",\"description\":\"小小年纪不肯退让半分，威风凛凛。\",\"approachTag\":\"【临阵不退】\",\"requirementHint\":\"气势骁勇\",\"statChanges\":{\"martial\":4,\"health\":4},\"outcomeText\":\"大白鹅嘎嘎叫着跳入水中，岸边浣纱的姑嫂们见状笑得前仰后合。\",\"eventFlagToSet\":\"done:evt_toddler_2_chasing_geese\"},{\"id\":\"c_geese_observe\",\"label\":\"躲在柳树干后细看大鹅捕食溪鱼与涉水姿势\",\"description\":\"静心观察万物造化之理。\",\"approachTag\":\"【格物细致】\",\"requirementHint\":\"敏于观察\",\"statChanges\":{\"intellect\":4,\"virtue\":2},\"outcomeText\":\"你领会了禽鸟水战之态，后来还以此想象水师舟楫的阵形。\",\"eventFlagToSet\":\"done:evt_toddler_2_chasing_geese\"},{\"id\":\"c_geese_share_berries\",\"label\":\"采摘溪边野黑莓塞入兜中，带回村中分给小伙伴们吃\",\"description\":\"乐于分享天真童趣。\",\"approachTag\":\"【乐群仗义】\",\"requirementHint\":\"人缘和顺\",\"statChanges\":{\"virtue\":4,\"wealth\":2},\"outcomeText\":\"孩子们围着你快活地跑跳，你成了村头孩童中最受欢迎的小伙伴。\",\"eventFlagToSet\":\"done:evt_toddler_2_chasing_geese\"}]', 1),
  ('evt_toddler_3_mudfish', 'INFANT_SURVIVAL', 70, NULL, 187, 187, '[0]', 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, '三岁春，你迈着小短腿跟在姐姐身后在田埂上捉泥鳅。泥水溅了一身，母亲笑着拿粗布替你擦洗小花脸。', NULL, NULL, '[]', 1),
  ('evt_toddler_3_stray_dog', 'INFANT_SURVIVAL', 85, NULL, 187, 187, '[2]', 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, '三岁深秋，一只瘦骨嶙峋的流浪小黄猎犬瑟瑟发抖蜷缩在自家柴门外，喉中发出哀鸣。', '秋风渐冷，眼前的小犬冻得直打颤，你打算如何对待它？', NULL, '[{\"id\":\"c_dog_feed\",\"label\":\"偷偷将自己粗陶碗里的半块苞谷面馍掰碎，蹲在地上喂给小狗\",\"description\":\"宁可自己饿肚子，也要给生灵一口活命口粮。\",\"approachTag\":\"【舍饭活命】\",\"requirementHint\":\"纯仁慈心，福佑自来\",\"statChanges\":{\"virtue\":6,\"health\":-2,\"fortune\":4},\"outcomeText\":\"小狗舐食干净后蹭着你的小腿撒欢，自此成了忠心耿耿护卫家院的看门家犬。\",\"eventFlagToSet\":\"done:evt_toddler_3_stray_dog\"},{\"id\":\"c_dog_bed\",\"label\":\"抱来干稻草与破草帘，在柴棚暖和角落为小犬搭建起避风小窝\",\"description\":\"懂得遮风避雨，妥善安置。\",\"approachTag\":\"【巧筑暖舍】\",\"requirementHint\":\"巧手仁心\",\"statChanges\":{\"intellect\":4,\"virtue\":4},\"outcomeText\":\"小狗在干草堆里安然沉睡，父亲赞你小小年纪便知安顿生灵。\",\"eventFlagToSet\":\"done:evt_toddler_3_stray_dog\"},{\"id\":\"c_dog_run\",\"label\":\"手持木棒带着小犬在晒谷场追逐奔跑，锻炼敏捷身手\",\"description\":\"活泼好动，奔走健步。\",\"approachTag\":\"【逐戏强身】\",\"requirementHint\":\"锻炼筋骨\",\"statChanges\":{\"health\":6,\"martial\":2},\"outcomeText\":\"你在阳光下跑得满头大汗，骨骼愈发壮实，身手远比寻常孩童灵巧。\",\"eventFlagToSet\":\"done:evt_toddler_3_stray_dog\"}]', 1),
  ('evt_child_4_storyteller', 'CHILDHOOD', 85, NULL, 188, 188, '[2]', 4, 4, NULL, NULL, NULL, NULL, NULL, NULL, '四岁秋，村口大槐树下来了一名断臂的老边卒，坐在石碾上向村童讲述当年随段颎征战西羌的豪勇往事。', '老兵挥舞仅存的独臂侃侃而谈，铁戈之声犹在耳畔，你最关心什么？', NULL, '[{\"id\":\"c_story_martial\",\"label\":\"双眼发光，追问当年汉军强弩连射、胡骑不敢近前的列阵技法\",\"description\":\"心慕军旅，对征战阵法极具向往。\",\"approachTag\":\"【向武求阵】\",\"requirementHint\":\"勇略初明\",\"statChanges\":{\"martial\":6,\"intellect\":4},\"outcomeText\":\"老卒拍着你的肩膀感叹：“好骨架！将来若投身军旅，定是斩将搴旗的好儿郎！”\",\"eventFlagToSet\":\"done:evt_child_4_storyteller\"},{\"id\":\"c_story_peace\",\"label\":\"关切地问：“打了那么多年的仗，死了那么多人，边地的百姓后来吃得上饭吗？”\",\"description\":\"悲天悯人，以民生疾苦为念。\",\"approachTag\":\"【仁者关怀】\",\"requirementHint\":\"仁政仁心\",\"statChanges\":{\"virtue\":6,\"intellect\":4},\"outcomeText\":\"老卒眼眶微红，长叹一声：“好孩子，圣贤之仁也不过如此，你懂老百姓的苦啊。”\",\"eventFlagToSet\":\"done:evt_child_4_storyteller\"},{\"id\":\"c_story_water\",\"label\":\"端来一角清冽井水奉给老卒润喉，老卒感激下赠你一枚磨平的建武五铢钱\",\"description\":\"尊老敬贤，懂礼知分。\",\"approachTag\":\"【尊师敬老】\",\"requirementHint\":\"礼仪周全，添得微资\",\"statChanges\":{\"virtue\":4,\"wealth\":4,\"fortune\":2},\"outcomeText\":\"老卒将那枚随身佩戴多年的汉五铢钱穿绳戴在你的颈上，祝愿你一生平顺。\",\"eventFlagToSet\":\"done:evt_child_4_storyteller\"}]', 1),
  ('evt_child_5_soldiers', 'CHILDHOOD', 70, NULL, 189, 189, '[2]', 5, 5, NULL, NULL, NULL, NULL, NULL, NULL, '五岁秋，洛阳大乱的消息传到乡间。一队疲惫不堪的败兵穿过村子，抢走了邻居家的两只老母鸡。你躲在柴垛后屏住呼吸，第一次见到了明晃晃的环首刀。', NULL, NULL, '[]', 1),
  ('evt_child_5_brush_fire', 'CHILDHOOD', 85, NULL, 189, 189, '[1]', 5, 5, NULL, NULL, NULL, NULL, NULL, NULL, '五岁夏日午后，炸雷击中山后老松，干燥的松针熊熊燃烧起来，黑烟顺风直逼村东麦场！', '烈火蔓延，形势危急，你小小年纪将作何举动？', NULL, '[{\"id\":\"c_fire_alarm\",\"label\":\"拼尽全身力气奔向村中祠堂，抓起木槌猛砸报警铜锣呼唤青壮\",\"description\":\"机变迅捷，先声夺人化解危局。\",\"approachTag\":\"【疾呼鸣警】\",\"requirementHint\":\"敏慧果决\",\"statChanges\":{\"intellect\":6,\"fortune\":4},\"outcomeText\":\"铜锣声震动全村，青壮们提着水桶木锹迅速赶到，在麦场前筑起隔火带扑灭大火！\",\"eventFlagToSet\":\"done:evt_child_5_brush_fire\"},{\"id\":\"c_fire_fight\",\"label\":\"扛起浸湿了的麻袋，跟着父兄冲上前线奋力拍打地表窜出的火苗\",\"description\":\"身先士卒，不畏烈焰烟熏。\",\"approachTag\":\"【冒火扑打】\",\"requirementHint\":\"刚勇无畏\",\"statChanges\":{\"martial\":6,\"health\":4,\"virtue\":4},\"outcomeText\":\"虽然眉毛被燎掉一撮，脸颊黑如锅底，但你英勇的表现令村中父老啧啧称奇。\",\"eventFlagToSet\":\"done:evt_child_5_brush_fire\"},{\"id\":\"c_fire_save_birds\",\"label\":\"冒着滚滚浓烟，从火舌舔舐的低矮灌木里掏出两只落难的灰雀雏鸟\",\"description\":\"危急之中不忘护生仁爱。\",\"approachTag\":\"【舍身救灵】\",\"requirementHint\":\"大悲慈念\",\"statChanges\":{\"virtue\":8,\"health\":2},\"outcomeText\":\"两只雏鸟在你怀中安然脱险，村老叹道：“此儿心存仁慈，必有天佑。”\",\"eventFlagToSet\":\"done:evt_child_5_brush_fire\"}]', 1),
  ('evt_child_6_refugees_winter', 'CHILDHOOD', 85, NULL, 190, 190, '[3]', 6, 6, NULL, NULL, NULL, NULL, NULL, NULL, '初平元年冬，董卓焚毁洛阳宫阙驱逼数百万军民西迁。一支数百人的流亡队伍冒着暴风雪穿过你们所在的县境，面有菜色，倒毙路旁者不知凡几。', '寒风呼号，篱笆外有衣衫褴褛的母子沿门乞讨，你打算如何相助？', NULL, '[{\"id\":\"c_refugee_soup\",\"label\":\"劝父母从地窖盛出一瓦罐滚烫的苞谷杂菜粥，端给门前冻僵的流亡母子\",\"description\":\"虽家境贫寒，但愿以一瓢热粥活人一命。\",\"approachTag\":\"【施粥救厄】\",\"requirementHint\":\"仁厚济世，折损微资\",\"statChanges\":{\"virtue\":10,\"wealth\":-2,\"fortune\":6},\"outcomeText\":\"饥寒交迫的妇人跪地泣谢，为你一家深切祈福。那一口热粥救下了两条性命。\",\"eventFlagToSet\":\"done:evt_child_6_refugees_winter\"},{\"id\":\"c_refugee_guard\",\"label\":\"手持削尖竹竿协助父亲警惕巡视篱院，防止心怀歹意的溃兵夜入劫掠\",\"description\":\"乱世防人之心不可无，卫护家宅周全。\",\"approachTag\":\"【严密拒盗】\",\"requirementHint\":\"机敏果决\",\"statChanges\":{\"martial\":6,\"intellect\":4},\"outcomeText\":\"几名形迹可疑的散兵见你家防备森严、少年目光如炬，悻悻退走，家中财物得以保全。\",\"eventFlagToSet\":\"done:evt_child_6_refugees_winter\"},{\"id\":\"c_refugee_inquire\",\"label\":\"向落魄的流亡老掌柜讨教洛阳火焚真相与关东各路诸侯的军情走向\",\"description\":\"通过天下流民之口洞悉大势变迁。\",\"approachTag\":\"【探问时局】\",\"requirementHint\":\"大开识见\",\"statChanges\":{\"intellect\":8,\"fortune\":2},\"outcomeText\":\"老掌柜细细为你描绘了西凉铁骑、曹公奋武、十八路诸侯歃血盟誓的格局，使你年仅六岁便对天下大势胸中有数。\",\"eventFlagToSet\":\"done:evt_child_6_refugees_winter\"}]', 1),
  ('evt_child_7_education', 'CHILDHOOD', 85, NULL, 191, 191, '[0]', 7, 7, NULL, NULL, NULL, NULL, NULL, NULL, '七岁春，汉家有“七岁学书数”之制。面对艰辛的家境，家里商量你的童年出路。', '七岁阳春，面对艰辛的家境，你打算如何打发童年岁月？', NULL, '[{\"id\":\"c_age7_cattle\",\"label\":\"在山坡田头替大户放牛割草，补贴家用\",\"description\":\"做个踏实懂事的苦力孩子，强筋健骨，分担父母重担。\",\"approachTag\":\"【勤苦耐劳】\",\"requirementHint\":\"朴实守分，强健体魄\",\"statChanges\":{\"health\":6,\"martial\":4,\"virtue\":4},\"outcomeText\":\"你在日光下晒得黝黑壮实，熟知山野草木，村中老少都夸你是个本分孝顺的好孩子。\",\"eventFlagToSet\":\"peasant_child\"},{\"id\":\"c_age7_study\",\"label\":\"站在乡里私塾窗外偷听老秀才讲授《孝经》与《千字文》\",\"description\":\"用枯树枝在地上划土练字，渴望明晓是非经义。\",\"approachTag\":\"【潜心向学】\",\"requirementHint\":\"需识见悟性\",\"statChanges\":{\"intellect\":10,\"virtue\":6,\"wealth\":-2},\"outcomeText\":\"塾师见你心诚，收了你两斤干红薯作修脯，教你辨认了三百个隶书汉字。\",\"eventFlagToSet\":\"studied_classics\"},{\"id\":\"c_age7_brawl\",\"label\":\"领着村里顽童削木刀演练“官军捉贼”，争当孩子王\",\"description\":\"生性胆壮，喜好听客商讲述吕布、关张万人敌的英雄故事。\",\"approachTag\":\"【崇武好斗】\",\"requirementHint\":\"敢打敢拼，勇略过人\",\"statChanges\":{\"martial\":8,\"health\":6,\"virtue\":-2},\"outcomeText\":\"你成了四乡八邻顽童的领头，上树摸鸟、下水摸鱼，胆魄过人。\",\"eventFlagToSet\":\"kid_leader\"}]', 1),
  ('evt_child_7_craftsman', 'CHILDHOOD', 85, NULL, 191, 191, '[2]', 7, 7, NULL, NULL, NULL, NULL, NULL, NULL, '七岁金秋，乡里大兴秋防修缮。村中几位老工匠欲在幼童中物色学徒，传授立身谋生之技。', '秋风初起，面对诸般手艺行当，你打算拜在何位长者门下学艺？', NULL, '[{\"id\":\"c_craft_bamboo\",\"label\":\"跟随老竹匠学习破篾编织斗笠、鱼篓与精细竹席\",\"description\":\"手艺轻巧精细，制作竹具既可家用亦能上市换铜钱。\",\"approachTag\":\"【巧手竹篾】\",\"requirementHint\":\"心灵手巧，补贴家资\",\"statChanges\":{\"intellect\":6,\"wealth\":6,\"health\":4},\"outcomeText\":\"你十指灵巧翻飞，编出的竹席紧密平滑，在集市上被抢购一空，挣得半匹粗布。\",\"eventFlagToSet\":\"done:evt_child_7_craftsman\"},{\"id\":\"c_craft_kiln\",\"label\":\"前往村头窑场帮老窑头挑黏土踩泥坯，烧造瓦盆砖石\",\"description\":\"窑火炽热，锻炼一副筋骨皮肉，吃得苦中苦。\",\"approachTag\":\"【陶泥窑火】\",\"requirementHint\":\"强筋健骨，气力扎实\",\"statChanges\":{\"health\":8,\"martial\":4,\"wealth\":4},\"outcomeText\":\"赤膊踩泥整整一季，你浑身皮肤晒成古铜色，双臂力道远超同龄稚童。\",\"eventFlagToSet\":\"done:evt_child_7_craftsman\"},{\"id\":\"c_craft_leather\",\"label\":\"拜村中老皮匠为师，学习硝制羊皮、缝合军马革具与刀鞘皮套\",\"description\":\"乱世甲仗兵具紧俏，皮具行当尤为诸侯军旅所需。\",\"approachTag\":\"【革甲皮工】\",\"requirementHint\":\"通晓甲具，兼顾武略\",\"statChanges\":{\"martial\":4,\"wealth\":8,\"intellect\":4},\"outcomeText\":\"你掌握了辨识良皮与硝皮鞣革秘诀，缝制的牛皮刀鞘结实耐用，受过往游侠交口称赞。\",\"eventFlagToSet\":\"done:evt_child_7_craftsman\"}]', 1),
  ('evt_child_8_mountain_hunt', 'CHILDHOOD', 85, NULL, 192, 192, '[3]', 8, 8, NULL, NULL, NULL, NULL, NULL, NULL, '初平三年冬，大雪封山。村中山民生计艰难，老猎户携猎犬与木弓进山捕冬兽，你执意随行。', '莽莽雪原之中，野兽足迹交错，面对突现的猎物踪迹，你如何展现身手？', NULL, '[{\"id\":\"c_hunt_shoot\",\"label\":\"伏在雪窝屏息凝神，待野兔窜出时果断引弦发矢，一箭命中\",\"description\":\"眼力毒辣，手稳心静，展现非凡射术潜质。\",\"approachTag\":\"【雪原发矢】\",\"requirementHint\":\"神射初显，武略大进\",\"statChanges\":{\"martial\":10,\"health\":6},\"outcomeText\":\"白羽小箭正中兔颈！老猎户拍大腿赞道：“好准头！真是天生百步穿杨的好手！”\",\"eventFlagToSet\":\"done:evt_child_8_mountain_hunt\"},{\"id\":\"c_hunt_trap\",\"label\":\"细察林间野兽粪便与踩枝痕迹，在兽道下巧妙设置竹篾绳套陷阱\",\"description\":\"用巧不用拙，智捕獐獾。\",\"approachTag\":\"【机巧伏阱】\",\"requirementHint\":\"智计并用，广获资粮\",\"statChanges\":{\"intellect\":8,\"martial\":4,\"wealth\":4},\"outcomeText\":\"次日清晨起网，陷阱中果然捕获两只肥硕岩獐，剥得两副完好皮毛与数十斤肉条。\",\"eventFlagToSet\":\"done:evt_child_8_mountain_hunt\"},{\"id\":\"c_hunt_share_elder\",\"label\":\"将自己分得的一大块鹿肉和皮坎肩，默默背去送给村中无儿无女的孤寡盲婆\",\"description\":\"幼怀仁心，敬老恤孤。\",\"approachTag\":\"【恤孤敬老】\",\"requirementHint\":\"至仁至善，福缘深广\",\"statChanges\":{\"virtue\":8,\"fortune\":6},\"outcomeText\":\"盲婆眼含浊泪抚摸你的双手，合掌祈愿上天保佑你长命百岁、仕途亨通。\",\"eventFlagToSet\":\"done:evt_child_8_mountain_hunt\"}]', 1),
  ('evt_child_9_river_ferry', 'CHILDHOOD', 85, NULL, 193, 193, '[1]', 9, 9, NULL, NULL, NULL, NULL, NULL, NULL, '初平四年盛夏，暴雨过后河水暴涨。县界渡口客商络绎不绝，老渡船夫病倒，你自告奋勇在津口顶班摆渡。', '大河浊浪翻滚，客商在岸边焦急呼唤，你当如何掌舵生息？', NULL, '[{\"id\":\"c_ferry_row\",\"label\":\"手握双橹稳立船头，借水势巧妙避开暗礁旋涡，稳渡行人\",\"description\":\"练就过人水性与臂力平衡。\",\"approachTag\":\"【掌舵破浪】\",\"requirementHint\":\"水性过人，强健体格\",\"statChanges\":{\"health\":8,\"martial\":6},\"outcomeText\":\"舟行如箭，稳若磐石！满船客商惊叹少年好胆色，上岸时纷纷多投数文打赏。\",\"eventFlagToSet\":\"done:evt_child_9_river_ferry\"},{\"id\":\"c_ferry_account\",\"label\":\"替渡口清点行囊杂物，按律核查官府过所文牒并分毫不差核算渡资\",\"description\":\"心思缜密，账目清白。\",\"approachTag\":\"【清点度支】\",\"requirementHint\":\"精打细算，积蓄微财\",\"statChanges\":{\"intellect\":8,\"wealth\":8},\"outcomeText\":\"一整日下来不仅分文未差，还识破了一名假冒符节的宵小，渡长重赏你八十文钱。\",\"eventFlagToSet\":\"done:evt_child_9_river_ferry\"},{\"id\":\"c_ferry_intelligence\",\"label\":\"坐在船舷向过往的行商镖客打探中原曹操、幽州公孙瓒与袁绍攻战的消息\",\"description\":\"留心四海风云，眼界超迈流俗。\",\"approachTag\":\"【留心军国】\",\"requirementHint\":\"洞察风云，开阔眼界\",\"statChanges\":{\"intellect\":6,\"martial\":4,\"fortune\":4},\"outcomeText\":\"镖师向你吐露了官军屯粮虚实与北方骑兵机变，使你对乱世全局有了极深见解。\",\"eventFlagToSet\":\"done:evt_child_9_river_ferry\"}]', 1),
  ('evt_child_10_illness', 'CHILDHOOD', 85, NULL, 194, 194, '[2]', 10, 10, NULL, NULL, NULL, NULL, NULL, NULL, '十岁金秋，母亲染上了咳喘虚热之疾，日渐消瘦。县城药铺掌柜索银六百钱，家中断无积蓄。', '母亲久病咳血，家中无银购药，面对危局你作何打算？', NULL, '[{\"id\":\"c_age10_herb\",\"label\":\"腰缚草绳攀爬荒山绝壁，亲自搜寻野生桔梗与柴胡\",\"description\":\"冒跌落悬崖与猛兽毒蛇之险，全凭一片赤诚孝心。\",\"approachTag\":\"【舍身采药】\",\"requirementHint\":\"纯孝至性，开通本草医理因果\",\"statChanges\":{\"health\":-4,\"virtue\":12,\"intellect\":4,\"fortune\":6},\"outcomeText\":\"手脚划出道道血口，终于采得数株野生紫草与金银花，煎汤服下后母亲热退神清，抱你垂泪。\",\"eventFlagToSet\":\"learned_herbs\"},{\"id\":\"c_age10_apprentice\",\"label\":\"跪在城内济世药铺门前，求掌柜收为三年杂役挑水切药换药材\",\"description\":\"以三年童工之身换取汤药，顺便偷学药理本草。\",\"approachTag\":\"【入肆学医】\",\"requirementHint\":\"识辨本草，开通医道因果\",\"statChanges\":{\"intellect\":8,\"wealth\":4,\"virtue\":6},\"outcomeText\":\"掌柜感你仁孝，赠了三副柴胡汤，并在药坊传授你辨认川贝、当归与黄芪的本草之术。\",\"eventFlagToSet\":\"learned_herbs\"},{\"id\":\"c_age10_borrow\",\"label\":\"向乡里放高利贷的豪强大户立下借券借粮换药\",\"description\":\"先救至亲性命，哪怕日后加倍做牛做马偿还。\",\"approachTag\":\"【负债救亲】\",\"requirementHint\":\"权宜救急，代价沉重\",\"statChanges\":{\"wealth\":-8,\"virtue\":4,\"fortune\":-2},\"outcomeText\":\"解了燃眉之急，但也欠下大户沉重债务，从此每年秋后都须去豪强田庄无偿做苦工。\"}]', 1),
  ('evt_child_11_locust_plague', 'CHILDHOOD', 90, NULL, 195, 195, '[1]', 11, 11, NULL, NULL, NULL, NULL, NULL, NULL, '兴平二年夏，天下大旱，漫天飞蝗遮天蔽日过境！草木禾稼顷刻被啃食一空，中原谷价腾贵，民相食，尸骸蔽野。', '蝗灾肆虐，田畴枯焦，存亡绝续之际你打算如何保全阖家与乡邻？', NULL, '[{\"id\":\"c_locust_trench\",\"label\":\"发动四邻少年连夜在田埂深挖火壕，引火泼油扑杀亿万飞蝗\",\"description\":\"机变设防，竭力抢救下南坡最后三分黍麦。\",\"approachTag\":\"【开壕焚蝗】\",\"requirementHint\":\"果断设谋，护粮救生\",\"statChanges\":{\"intellect\":8,\"martial\":6,\"virtue\":6},\"outcomeText\":\"熊熊壕火烧焦了遮天蝗群，奇迹般护住了村后数十石成熟谷穗，全村老幼感激啼零。\",\"eventFlagToSet\":\"done:evt_child_11_locust_plague\"},{\"id\":\"c_locust_kudzu\",\"label\":\"背负药锄与竹篓深入大山断崖，挖掘肥厚葛根、剥取榆树皮磨粉\",\"description\":\"跋山涉水搜寻代粮之物，全凭坚韧求生。\",\"approachTag\":\"【掘葛充饥】\",\"requirementHint\":\"耐苦忍劳，保全家人\",\"statChanges\":{\"health\":6,\"virtue\":8,\"fortune\":4},\"outcomeText\":\"你挖得数十斤肥嫩葛根并晒制成救命葛粉，靠着这口微薄清苦之粮，一家人挺过了绝粮荒月。\",\"eventFlagToSet\":\"done:evt_child_11_locust_plague\"},{\"id\":\"c_locust_fair_grain\",\"label\":\"协助里正主持公道，平粜互助分发存粮，严防豪强奸商囤积居奇\",\"description\":\"身正不阿，维系乡井安宁。\",\"approachTag\":\"【平粜救民】\",\"requirementHint\":\"主持公道，大德在躬\",\"statChanges\":{\"virtue\":10,\"intellect\":6,\"wealth\":-4},\"outcomeText\":\"你秉公分配每一合黍米，制止了多起饥民械斗抢粮，村社虽清贫却守望相助，无一人饿毙。\",\"eventFlagToSet\":\"done:evt_child_11_locust_plague\"}]', 1),
  ('evt_child_12_traveling_doctor', 'CHILDHOOD', 85, NULL, 196, 196, '[0]', 12, 12, NULL, NULL, NULL, NULL, NULL, NULL, '建安元年春，一位游方名医携药囊路宿乡舍。你手脚麻利端茶研墨，医者见你天资颖悟，允你随行观摩诊治。', '名医坐堂施诊，病患盈门，你愿从何处着手领悟医道真谛？', NULL, '[{\"id\":\"c_doctor_herbs\",\"label\":\"研习《神农本草》，细心辨识黄连、柴胡、当归等药性寒热温凉\",\"description\":\"通晓药理，下苦功背诵汤头歌诀。\",\"approachTag\":\"【精研本草】\",\"requirementHint\":\"通达医理，启智益慧\",\"statChanges\":{\"intellect\":10,\"virtue\":6,\"health\":4},\"outcomeText\":\"你一月内谙熟百种本草方剂，老医者赠你一本手抄经方笔记，赞你日后足可悬壶济世。\",\"eventFlagToSet\":\"done:evt_child_12_traveling_doctor\"},{\"id\":\"c_doctor_care\",\"label\":\"不避恶臭污秽，亲自为长满烂疮的流浪老丐清洗创口并包扎草药\",\"description\":\"医者仁心，视病家若至亲。\",\"approachTag\":\"【悬壶仁心】\",\"requirementHint\":\"大仁大慈，修积阴德\",\"statChanges\":{\"virtue\":10,\"health\":4,\"fortune\":6},\"outcomeText\":\"老丐创口收敛愈合，感激涕零叩首。你的仁义之名在十里八乡广为传颂。\",\"eventFlagToSet\":\"done:evt_child_12_traveling_doctor\"},{\"id\":\"c_doctor_trauma\",\"label\":\"借阅金创外伤医典，仔细琢磨刀矛创伤止血缝合与正骨之法\",\"description\":\"心系沙场创伤救护，为乱世立身做好准备。\",\"approachTag\":\"【精于金创】\",\"requirementHint\":\"通晓战阵救护\",\"statChanges\":{\"intellect\":12,\"martial\":4},\"outcomeText\":\"你掌握了战场急救、白药止血与木板固定骨折之奇术，后来多番救助乡勇伤兵。\",\"eventFlagToSet\":\"done:evt_child_12_traveling_doctor\"}]', 1),
  ('evt_child_13_tame_warhorse', 'CHILDHOOD', 85, NULL, 197, 197, '[2]', 13, 13, NULL, NULL, NULL, NULL, NULL, NULL, '建安二年秋，一匹受创走失的军阵青骢烈马狂奔入村边高粱地。烈马性如烈火、双蹄扬尘，数名壮汉莫敢近前。', '通体矫健的神骏战马喷着白沫喘息，蹄下踏烂禾苗，你打算如何处置？', NULL, '[{\"id\":\"c_horse_leap\",\"label\":\"瞅准时机纵身跃上光溜溜的马背，死死抱住马颈任其在荒原狂奔直至驯伏\",\"description\":\"胆魄通天，以超凡蛮力与平衡降服烈驹。\",\"approachTag\":\"【翻身伏驹】\",\"requirementHint\":\"骑术通神，勇烈超群\",\"statChanges\":{\"martial\":12,\"health\":6,\"fortune\":4},\"outcomeText\":\"狂奔十里之后烈马终于低头打响鼻臣服，村中老少见你策马徐行归来，无不欢呼雷动！\",\"eventFlagToSet\":\"done:evt_child_13_tame_warhorse\"},{\"id\":\"c_horse_tend\",\"label\":\"捧出淡盐水与甜苜蓿草轻声诱抚，小心拔出其后蹄嵌入的锈蚀断箭\",\"description\":\"以柔克刚，以仁心抚平战马恐惧。\",\"approachTag\":\"【温言抚创】\",\"requirementHint\":\"通灵性，积仁德\",\"statChanges\":{\"virtue\":6,\"intellect\":8,\"fortune\":6},\"outcomeText\":\"烈马痛楚消除，亲昵地以头蹭你的前襟。战马认你为主，自此朝夕相随。\",\"eventFlagToSet\":\"done:evt_child_13_tame_warhorse\"},{\"id\":\"c_horse_return\",\"label\":\"制伏战马后依军号烙印送还县府兵曹，换得赏钱三千文与一领良绢\",\"description\":\"遵从法度，换取扎实家私。\",\"approachTag\":\"【奉公还官】\",\"requirementHint\":\"遵纪守法，家产丰实\",\"statChanges\":{\"wealth\":10,\"virtue\":4,\"intellect\":4},\"outcomeText\":\"县尉大喜，不仅全数颁发赏银，还在考功簿上记下你的忠顺义行。\",\"eventFlagToSet\":\"done:evt_child_13_tame_warhorse\"}]', 1),
  ('evt_adult_14_vocation', 'RITE_OF_PASSAGE', 85, NULL, 198, 198, '[1]', 14, 14, NULL, NULL, NULL, NULL, NULL, NULL, '十四岁夏，行将成丁束发。官府查验户籍簿，各方诸侯四处征收力役，正需自立谋生。', '成丁立身之际，你打算以何等行当开始养家糊口？', NULL, '[{\"id\":\"c_age14_blacksmith\",\"label\":\"在县城铁匠铺拜师，学习锻造环首长刀与农耕犁头\",\"description\":\"乱世铁匠吃香，既能打造农具，亦能修造兵甲。\",\"approachTag\":\"【铁匠精工】\",\"requirementHint\":\"淬火锻钢，强健身骨\",\"statChanges\":{\"martial\":8,\"health\":8,\"wealth\":6},\"outcomeText\":\"炉火映红了你的脸膛，三年抡锤练得浑身精肉，打造的短刀削铁如泥，备受好评。\",\"eventFlagToSet\":\"blacksmith_master\"},{\"id\":\"c_age14_boatman\",\"label\":\"投效江河船帮，随运粮商船南下江东贩卖土特\",\"description\":\"走南闯北，多长见识，江河虽有风浪，但利钱颇丰。\",\"approachTag\":\"【舟楫商贩】\",\"requirementHint\":\"涉险风浪，博取商资\",\"statChanges\":{\"wealth\":14,\"intellect\":8,\"health\":-4,\"fortune\":4},\"outcomeText\":\"你随船历经长江与汉水，熟悉了水流暗礁，还学会了与水贼及关税差役打交道。\",\"eventFlagToSet\":\"boatman_master\"},{\"id\":\"c_age14_scribe\",\"label\":\"在县衙户曹当一名书办抄手，登记粮库流水账目\",\"description\":\"吃官家一口薄粥，结交里正亭长，明晓律令规矩。\",\"approachTag\":\"【笔墨文吏】\",\"requirementHint\":\"需识见聪敏\",\"statChanges\":{\"intellect\":12,\"wealth\":6,\"virtue\":4},\"outcomeText\":\"你写得一手整饬的汉隶，账目明晰，县丞夸你是个可用之才。\",\"eventFlagToSet\":\"scribe_clerk\"}]', 1),
  ('evt_youth_14_market_trading', 'RITE_OF_PASSAGE', 85, NULL, 198, 198, '[2]', 14, 14, NULL, NULL, NULL, NULL, NULL, NULL, '建安三年秋，郡界设立榷场互市。塞外胡马、关东布帛与巴蜀盐铁汇聚于此，人声鼎沸，商机涌动。', '市集熙攘，胡商汉贾云集，你欲如何在这大市之中博取人生资财与见识？', NULL, '[{\"id\":\"c_trade_profit\",\"label\":\"准确研判四方物价短缺，低吸高抛贩运粗麻丝绢与塞外皮毛\",\"description\":\"审时度势，抓住商机博取第一桶丰厚本金。\",\"approachTag\":\"【转运商贾】\",\"requirementHint\":\"精敏通达，家业大兴\",\"statChanges\":{\"wealth\":16,\"intellect\":8},\"outcomeText\":\"你算无遗策，几番倒手净赚三十余金，在乡里置办下两头健壮耕牛与五亩良田。\",\"eventFlagToSet\":\"done:evt_youth_14_market_trading\"},{\"id\":\"c_trade_friends\",\"label\":\"在榷场酒肆中慷慨沽酒，结纳押货护镖的各路游侠与关防牙将\",\"description\":\"仗义疏财，结交草莽豪杰与军伍朋友。\",\"approachTag\":\"【游侠豪客】\",\"requirementHint\":\"广交豪杰，武略大长\",\"statChanges\":{\"martial\":10,\"intellect\":6,\"fortune\":4},\"outcomeText\":\"游侠们与你歃血论交，传授你贴身短刀与防贼暗器之道，四方朋友皆尊你一声“小义士”。\",\"eventFlagToSet\":\"done:evt_youth_14_market_trading\"},{\"id\":\"c_trade_justice\",\"label\":\"据理力争怒斥奸商缺斤短两、掺假压榨边地卖桑妇孺，当街主持秤量公道\",\"description\":\"铁面无私，扶危济弱。\",\"approachTag\":\"【主持市秤】\",\"requirementHint\":\"浩然正气，深孚众望\",\"statChanges\":{\"virtue\":12,\"martial\":6,\"fortune\":4},\"outcomeText\":\"市监主簿大为激赏你的骨鲠正气，当场勒令奸商赔偿，榷场商民无不高声喝彩。\",\"eventFlagToSet\":\"done:evt_youth_14_market_trading\"}]', 1),
  ('evt_youth_15_mountain_recluse', 'RITE_OF_PASSAGE', 85, NULL, 199, 199, '[0]', 15, 15, NULL, NULL, NULL, NULL, NULL, NULL, '建安四年春，听闻深山幽谷之中隐居着一位名动天下的古文学派大儒。你不辞辛劳，攀岩涉涧求见。', '青松之下，清泉石上，白发老儒拂琴而坐，淡然问你：“少年人涉险登山，所求者何？”', NULL, '[{\"id\":\"c_recluse_classics\",\"label\":\"深施长揖，恭谨请教《左氏春秋》治乱之道与天下兴亡宿命\",\"description\":\"探求天下兴亡大略，明了经邦济世之理。\",\"approachTag\":\"【春秋大义】\",\"requirementHint\":\"洞悉治道，大开宏略\",\"statChanges\":{\"intellect\":14,\"virtue\":8},\"outcomeText\":\"大儒长叹良久，倾囊相授治政得失与人主用人之道，赞你：“胸罗甲兵，识见深远，非寻常匹夫也。”\",\"eventFlagToSet\":\"done:evt_youth_15_mountain_recluse\"},{\"id\":\"c_recluse_zen\",\"label\":\"在松涛清泉旁为先生烹煮野茶，静心聆听素琴高山流水之操\",\"description\":\"涵养超然豁达之性情，波澜不惊。\",\"approachTag\":\"【淡泊明志】\",\"requirementHint\":\"宁静致远，性灵澄澈\",\"statChanges\":{\"virtue\":12,\"health\":8,\"fortune\":8},\"outcomeText\":\"先生赠你一曲琴谱，教你修身养气之秘术。你自此神清气朗，大难临头亦能安之若素。\",\"eventFlagToSet\":\"done:evt_youth_15_mountain_recluse\"},{\"id\":\"c_recluse_ambition\",\"label\":\"昂首慨然直言：“乱世兵戈四起，生灵涂炭！晚辈欲提三尺长剑荡平妖氛，求先生传破敌兵法！”\",\"description\":\"胸怀大志，誓要在乱世建功立业。\",\"approachTag\":\"【慷慨剑气】\",\"requirementHint\":\"志在四方，军略初成\",\"statChanges\":{\"martial\":10,\"intellect\":10,\"fortune\":4},\"outcomeText\":\"大儒目光如炬审视你良久，点头取出一卷珍藏的姜太公《阴符残篇》赠予你：“好儿郎，莫负天下苍生！”\",\"eventFlagToSet\":\"done:evt_youth_15_mountain_recluse\"}]', 1),
  ('evt_youth_15_village_militia', 'RITE_OF_PASSAGE', 85, NULL, 199, 199, '[3]', 15, 15, NULL, NULL, NULL, NULL, NULL, NULL, '建安四年严冬，各方大战在即，山匪流寇频出。乡党自发组织青壮设立“保境乡勇”，在校场厉兵秣马。', '朔风凛冽，全乡数十名青壮手执矛戈齐聚校场，你当如何一展身手？', NULL, '[{\"id\":\"c_militia_archery\",\"label\":\"双臂挽开一石六斗硬木拓弓，在狂风中连发三箭皆中百步外红心\",\"description\":\"神乎其技，震慑四野，被众乡亲推举为乡勇箭队队长。\",\"approachTag\":\"【箭震校场】\",\"requirementHint\":\"弓马娴熟，威震乡党\",\"statChanges\":{\"martial\":14,\"health\":6},\"outcomeText\":\"喝彩声如雷！众青壮心悦诚服，皆愿随你巡逻要隘，流寇闻你神射威名不敢犯境。\",\"eventFlagToSet\":\"done:evt_youth_15_village_militia\"},{\"id\":\"c_militia_tactics\",\"label\":\"向乡尊献上防御图纸，提议依山势设立深沟暗桩与烽火狼烟台\",\"description\":\"运筹帷幄，以兵阵工程之力严防死守。\",\"approachTag\":\"【坚壁固守】\",\"requirementHint\":\"算无遗策，军法森严\",\"statChanges\":{\"intellect\":12,\"martial\":6},\"outcomeText\":\"你督造的暗堡与伏路机巧让数股窜犯的小股马贼碰得头破血流，县令亲赐旌旗褒奖。\",\"eventFlagToSet\":\"done:evt_youth_15_village_militia\"},{\"id\":\"c_militia_logistics\",\"label\":\"负责统筹督办乡勇数十人每日干粮、草鞋与伤药配发，分毫毕现\",\"description\":\"治后勤辎重井井有条，深孚众心。\",\"approachTag\":\"【管领辎重】\",\"requirementHint\":\"治军严明，仁信兼备\",\"statChanges\":{\"intellect\":8,\"wealth\":6,\"virtue\":8},\"outcomeText\":\"每位乡勇冬夜都有热汤与干粮，军心大定。乡老皆叹：“此子通晓军需根本，乃大将佐贰之才！”\",\"eventFlagToSet\":\"done:evt_youth_15_village_militia\"}]', 1),
  ('evt_adult_18_conscription', 'RITE_OF_PASSAGE', 85, NULL, 200, 202, '[1,2]', 16, 20, NULL, NULL, NULL, '[\"done:evt_adult_18_conscription\"]', NULL, NULL, '天下诸侯割据争锋，各地广发从军召募文告，铜锣声震动四野。值此及冠成丁之际，正是决定投效何方阵营的关键时刻！', '天下诸侯纷争，营门大开召募勇士，你决定投身何方阵营，或自留乡间务农？', NULL, '[{\"id\":\"c_enlist_yuan_shao\",\"label\":\"【投效河北袁绍军】投奔河北大将军袁本初麾下，入编大戟先锋亲骑\",\"description\":\"袁绍坐拥幽青并冀四州，带甲数十万，兵精粮足，为天下第一霸主！\",\"approachTag\":\"【河北大军】\",\"requirementHint\":\"需体魄筋骨强健\",\"statChanges\":{\"martial\":12,\"health\":6,\"wealth\":8,\"fortune\":4},\"outcomeText\":\"你领到一具精铁扎甲与丈八硬槊，被编入袁大将军帐前前锋营，士气如虹！\",\"campaignUnlock\":{\"campaignName\":\"行伍投军 · 河北\",\"camp\":\"YUAN_SHAO\",\"commander\":\"袁绍\",\"roleTitle\":\"河北袁绍帐前亲骑\"},\"eventFlagToSet\":\"done:evt_adult_18_conscription\"},{\"id\":\"c_enlist_cao_cao\",\"label\":\"【投效中原曹魏营】投奔司空曹公兖州大营，立志做一名破阵步骑\",\"description\":\"曹公奉天子以令不臣，唯才是举，治军森严，乃中原雄主！\",\"approachTag\":\"【曹魏雄师】\",\"requirementHint\":\"需勇略过人\",\"statChanges\":{\"martial\":14,\"intellect\":6,\"wealth\":6,\"fortune\":-2},\"outcomeText\":\"你通过军门校阅，被编入曹公麾下正规战兵，发放环首长刀与皮胄。\",\"campaignUnlock\":{\"campaignName\":\"行伍投军 · 曹营\",\"camp\":\"WEI\",\"commander\":\"曹操\",\"roleTitle\":\"曹公帐前亲兵步卒\"},\"eventFlagToSet\":\"done:evt_adult_18_conscription\"},{\"id\":\"c_enlist_liu_bei\",\"label\":\"【投效刘玄德义师】投奔以仁德著称的刘玄德与常山赵子龙\",\"description\":\"刘备虽屡经屯邅，然仁厚得民，关张赵皆万人敌，誓保汉家山河！\",\"approachTag\":\"【仁德义从】\",\"requirementHint\":\"需仁厚仁义\",\"statChanges\":{\"virtue\":16,\"martial\":10,\"health\":4,\"wealth\":-4},\"outcomeText\":\"刘玄德亲握你手好言相慰，赵子龙为你正衣冠。虽军容简朴，然将士同心同德！\",\"campaignUnlock\":{\"campaignName\":\"行伍投军 · 刘义师\",\"camp\":\"SHU\",\"commander\":\"赵云\",\"roleTitle\":\"玄德亲军义从步卒\"},\"eventFlagToSet\":\"done:evt_adult_18_conscription\"},{\"id\":\"c_enlist_leave_civilian\",\"label\":\"【下野拒绝入伍】托请里正通融，宁愿多缴赋税，留在家乡耕织安生\",\"description\":\"远离诸侯杀伐征战的绞肉机，做一个本分安生的乡野耕民。\",\"approachTag\":\"【躬耕避战】\",\"requirementHint\":\"耗费微财，求得安宁\",\"statChanges\":{\"wealth\":-8,\"virtue\":6,\"fortune\":6},\"outcomeText\":\"你躲过了官府抽丁的鞭梢，安心留在家乡耕种一亩三分地，免去沙场尸骨无存之苦。\",\"leaveMilitary\":true,\"eventFlagToSet\":\"done:evt_adult_18_conscription\"}]', 1),
  ('evt_adult_24_marriage', 'RITE_OF_PASSAGE', 80, NULL, 208, 208, '[0]', 24, 24, NULL, NULL, NULL, NULL, NULL, NULL, '二十四岁阳春。乡邻见你为人诚笃勤奋，有村老主动为你做媒，说合邻庄勤谨温厚的刘氏女子。', '草民成家之机，你是否应允这门亲事？', NULL, '[{\"id\":\"c_age24_marry\",\"label\":\"拿出多年积攒的二千铜钱与四匹粗布，下聘迎娶刘氏为妻\",\"description\":\"在这风雨飘摇的人间，为自己寻一个相濡以沫的温存港湾。\",\"approachTag\":\"【结发同心】\",\"requirementHint\":\"需备薄资下聘\",\"statChanges\":{\"virtue\":10,\"health\":6,\"wealth\":-12},\"outcomeText\":\"两盏浊酒，红烛摇曳。你与刘氏结发为夫妻，茅屋之中从此有了炊烟笑语。次年为你添了麟儿。\",\"eventFlagToSet\":\"married\"},{\"id\":\"c_age24_hoard_grain\",\"label\":\"婉言谢绝媒人，专心置办地窖藏购干粮肉干以防荒乱\",\"description\":\"世道险恶战乱无常，不敢轻易拖累妻儿妇孺。\",\"approachTag\":\"【积谷防饥】\",\"requirementHint\":\"独善其身，积蓄资粮\",\"statChanges\":{\"wealth\":16,\"intellect\":6,\"virtue\":-2},\"outcomeText\":\"你将积蓄换成了数十石高粱大麦深埋地窖，在这乱世为自己攒下了一道保命屏障。\",\"eventFlagToSet\":\"hoarded_grain\"}]', 1),
  ('evt_campaign_190_hulao', 'HISTORICAL_CAMPAIGN', 100, '虎牢关会盟讨董', 190, 190, '[0,1]', 15, 65, NULL, NULL, NULL, '[\"done:evt_campaign_190_hulao\"]', NULL, NULL, '初平元年，关东十八路诸侯歃血结盟讨董！华雄在关前连斩联军数将，西凉铁骑威压洛阳要隘。战鼓震天动地，你亲临前沿营阵！', '十八路诸侯歃血讨董，华雄搦战，温酒斩将！你身在行伍，当如何立功？', NULL, '[{\"id\":\"c_hulao_charge\",\"label\":\"执大纛随先锋大队直扑虎牢关隘，迎战西凉铁骑\",\"description\":\"擂鼓震天，箭石如雨。不惧生死，立下先登之功！\",\"approachTag\":\"【先登陷阵】\",\"requirementHint\":\"需体魄与勇略出众\",\"statChanges\":{\"martial\":12,\"health\":4,\"virtue\":6,\"wealth\":8},\"outcomeText\":\"你挥枪击落两名西凉飞熊骑兵，夺得一面敌旗！军候为你记大功一次，赏铜钱千文。\",\"campaignUnlock\":{\"campaignName\":\"虎牢关会盟讨董\",\"camp\":\"SHU\",\"commander\":\"赵云\",\"roleTitle\":\"帐前陷阵勇卒\"},\"eventFlagToSet\":\"done:evt_campaign_190_hulao\"},{\"id\":\"c_hulao_scout\",\"label\":\"潜入汴水两岸密林，打探董卓后军粮道与伏兵\",\"description\":\"依仗敏锐机警，为后方大营预警徐荣伏兵。\",\"approachTag\":\"【机敏游哨】\",\"requirementHint\":\"需识见通达\",\"statChanges\":{\"intellect\":10,\"fortune\":8,\"virtue\":4},\"outcomeText\":\"你在汴水树丛中发觉徐荣伏兵痕迹，疾驰回营报信，使得数百友军幸免于全军覆没！\",\"campaignUnlock\":{\"campaignName\":\"虎牢关会盟讨董\",\"camp\":\"WEI\",\"commander\":\"曹操\",\"roleTitle\":\"机警斥候队长\"},\"eventFlagToSet\":\"done:evt_campaign_190_hulao\"}]', 1),
  ('evt_campaign_196_xuchang_tuntian', 'HISTORICAL_CAMPAIGN', 95, '许昌大兴屯田', 196, 197, '[1,2]', 16, 65, NULL, NULL, NULL, '[\"done:evt_campaign_196_tuntian\"]', NULL, NULL, '建安元年曹操奉天子迁都许昌，颁布天下闻名的“屯田令”，召募流民百姓开垦淮北荒田，官府供耕牛农具，分岁收获利！', '曹公屯田令下达，许昌四野大开屯田，你作何决算？', NULL, '[{\"id\":\"c_tuntian_clerk\",\"label\":\"应募出任典农校尉麾下督粮小吏，度量荒田分配牛种\",\"description\":\"协助官府规划水渠与粮仓，保一方军民糊口。\",\"approachTag\":\"【典农法度】\",\"requirementHint\":\"需识见通晓文墨\",\"statChanges\":{\"intellect\":12,\"wealth\":10,\"virtue\":6},\"outcomeText\":\"你划分沟洫公允整饬，当年许下大熟，得谷百万斛！典农中郎将任峻嘉奖你的治政才干。\",\"campaignUnlock\":{\"campaignName\":\"许昌大兴屯田\",\"camp\":\"WEI\",\"commander\":\"曹操\",\"roleTitle\":\"典农都尉督粮官\"},\"eventFlagToSet\":\"done:evt_campaign_196_tuntian\"},{\"id\":\"c_tuntian_farm\",\"label\":\"领下官牛三十亩荒田，带领宗族开荒深耕\",\"description\":\"脚踏实地耕作，在这个兵荒马乱的乱世为全家争取稳定的粮食与片瓦遮风。\",\"approachTag\":\"【躬耕安民】\",\"requirementHint\":\"勤力稼穑，保障口粮\",\"statChanges\":{\"health\":8,\"wealth\":14,\"virtue\":4},\"outcomeText\":\"汗水浇灌之下，荒地变良田！秋后谷粒堆满草仓，一家老小再无断顿饥馑之忧。\",\"eventFlagToSet\":\"done:evt_campaign_196_tuntian\"}]', 1),
  ('evt_guandu_200_yuanshao_wuchao', 'HISTORICAL_CAMPAIGN', 100, '官渡之战 · 乌巢生死', 200, 200, '[2,3]', 16, 65, 'YUAN_SHAO', NULL, NULL, '[\"done:evt_guandu\"]', NULL, NULL, '建安五年冬十月，两军对峙官渡半年。你随大将淳于琼驻守袁绍军粮命脉——乌巢万车粮囤。夜半三更，曹操亲统五千精锐轻骑衔枚夜袭，四面纵火，万车军粮顿陷火海！淳于琼惊起披甲，大营溃乱，曹骑铁蹄呼啸而至！', '乌巢烈火连天，万车粮囤尽毁，曹公亲提精骑四面围杀，你身陷重围，当作何决断？', NULL, '[{\"id\":\"c_wuchao_fight_death\",\"label\":\"【誓死守护】挺枪冲入烈火与曹军突骑决一死战，誓保万车粮仓\",\"description\":\"面对曹操虎豹骑突击，死战不退！若武略体魄不足将当场战死，壮烈殉节。\",\"approachTag\":\"【忠烈死节】\",\"requirementHint\":\"需极高体魄与勇略\",\"statChanges\":{\"martial\":14,\"virtue\":10,\"health\":-15},\"outcomeText\":\"你持枪格杀数名曹军精骑，然烈火四合、寡不敌众，身负重伤倒地，被曹军擒获押解至营前！\",\"followUpChoice\":{\"prompt\":\"你力战身负重创，被缚于曹操大帐辕门之下。曹公按剑而视，面临生死关口！\",\"options\":[{\"id\":\"c_wuchao_sub_surrender\",\"label\":\"【俯首降曹】向曹公下拜愿降，誓效犬马之劳\",\"description\":\"识时务者为俊杰，脱离河北败军，编入曹营效命。\",\"approachTag\":\"【归顺新主】\",\"requirementHint\":\"保全性命，洗刷旧籍\",\"statChanges\":{\"intellect\":8,\"wealth\":6,\"virtue\":-6},\"outcomeText\":\"曹操亲手为你解开绳索，赐酒一口，赞你守囤之勇，擢升为曹军步营牙门正卒！自此改属曹魏。\",\"campaignUnlock\":{\"campaignName\":\"官渡归降曹公\",\"camp\":\"WEI\",\"commander\":\"曹操\",\"roleTitle\":\"曹营降将牙门卒\"},\"eventFlagToSet\":\"done:evt_guandu\"},{\"id\":\"c_wuchao_sub_escape_civilian\",\"label\":\"【趁乱下野】趁押解松懈脱掉皮甲弃械，趁夜色荒草逃回故里务农\",\"description\":\"抛弃刀兵浮名，脱离军伍归隐田园，保全余生。\",\"approachTag\":\"【解甲归田】\",\"requirementHint\":\"下野还乡，保全性命\",\"statChanges\":{\"virtue\":6,\"wealth\":-4,\"fortune\":8},\"outcomeText\":\"你趁曹军忙于抢缴粮秣看守松懈，滚入芦苇荡潜逃，隐姓埋名逃回故里，免去随袁军被坑杀之祸！\",\"leaveMilitary\":true,\"eventFlagToSet\":\"done:evt_guandu\"},{\"id\":\"c_wuchao_sub_die_martyr\",\"label\":\"【痛骂就义】挺胸怒斥曹瞒乃汉贼，宁死不降\",\"description\":\"引颈受戮，誓死不从国贼，尽显河北男儿刚烈风骨！\",\"approachTag\":\"【成仁取义】\",\"requirementHint\":\"舍生取义，名留青史\",\"statChanges\":{\"virtue\":25},\"outcomeText\":\"你慷慨痛骂曹操，刀斧手挥刃就戮，从容赴死。\",\"isDirectFatal\":true,\"fatalDeathReason\":\"官渡乌巢战后被俘，誓死不从曹贼，慷慨就义于辕门。\"}]}},{\"id\":\"c_wuchao_captured_branch\",\"label\":\"【兵败被俘】拼死突围但身负重创力竭被擒，押解至曹营大帐\",\"description\":\"突围不及陷入重围，沦为曹军俘虏，面临命运抉择。\",\"approachTag\":\"【临阵受缚】\",\"requirementHint\":\"被俘待决\",\"statChanges\":{\"health\":-10,\"martial\":4},\"outcomeText\":\"你拼死突围却被绊马索绊倒，曹军甲士将你五花大绑押至曹操辕门大营！\",\"followUpChoice\":{\"prompt\":\"你被押至曹公帐前，曹操问：“降否？”你作何决断？\",\"options\":[{\"id\":\"c_wuchao_cap_surrender\",\"label\":\"【俯首降曹】叩首愿降，改换门庭转投曹公麾下\",\"description\":\"投入曹魏阵营，保全性命与一身本领。\",\"approachTag\":\"【改投明主】\",\"requirementHint\":\"改换阵营\",\"statChanges\":{\"intellect\":6,\"wealth\":8,\"virtue\":-4},\"outcomeText\":\"曹操颔首收纳，将你编入曹营先锋队正，自此成为曹魏一员。\",\"campaignUnlock\":{\"campaignName\":\"官渡乌巢降曹\",\"camp\":\"WEI\",\"commander\":\"曹操\",\"roleTitle\":\"曹营行伍步卒\"},\"eventFlagToSet\":\"done:evt_guandu\"},{\"id\":\"c_wuchao_cap_resign\",\"label\":\"【下野求生】谎称后勤伙夫求免一死，趁夜翻出营墙下野还乡\",\"description\":\"从此脱离军旅，不再过问诸侯厮杀，隐入田舍。\",\"approachTag\":\"【脱甲还乡】\",\"requirementHint\":\"恢复平民身份\",\"statChanges\":{\"virtue\":4,\"wealth\":-6,\"fortune\":6},\"outcomeText\":\"你假扮役夫脱身逃遁，昼伏夜行跋涉千里潜回河北故里，做一个平头百姓度日。\",\"leaveMilitary\":true,\"eventFlagToSet\":\"done:evt_guandu\"},{\"id\":\"c_wuchao_cap_martyr\",\"label\":\"【誓死不从】破口痛骂，慷慨就义\",\"description\":\"绝不屈膝事敌，以死全节。\",\"approachTag\":\"【浩气长存】\",\"requirementHint\":\"从容就义\",\"statChanges\":{\"virtue\":20},\"outcomeText\":\"刀光过处，血溅辕门，终不失河北忠勇之名！\",\"isDirectFatal\":true,\"fatalDeathReason\":\"官渡被俘后坚贞不屈，大骂曹贼，慷慨就义于辕门。\"}]}},{\"id\":\"c_wuchao_resign_escape\",\"label\":\"【见机下野】眼见粮仓焚尽、大势已去，趁夜色火光脱下军服潜逃回河北故里\",\"description\":\"审时度势，脱离已溃散的袁军死地，避免被围歼坑杀。\",\"approachTag\":\"【潜逃脱身】\",\"requirementHint\":\"脱离军伍，保全性命\",\"statChanges\":{\"intellect\":8,\"fortune\":8,\"martial\":-2},\"outcomeText\":\"你趁四野混乱脱掉军甲潜入芦苇沼泽，借着夜色一路向北奔逃，终于安然返回河北老家务农。\",\"leaveMilitary\":true,\"eventFlagToSet\":\"done:evt_guandu\"}]', 1),
  ('evt_guandu_200_caocao_attack', 'HISTORICAL_CAMPAIGN', 100, '官渡之战 · 乌巢奇袭', 200, 200, '[2,3]', 16, 65, 'WEI', NULL, NULL, '[\"done:evt_guandu\"]', NULL, NULL, '官渡相持半年，两军粮少兵疲！许攸深夜脱逃来降，献乌巢屯粮虚实。曹操亲提五千轻骑，人衔枚马缚口，趁夜直扑袁绍粮囤！', '许攸深夜献粮道密图，曹公亲提五千轻骑衔枚夜行，疾袭乌巢万车军粮！', NULL, '[{\"id\":\"c_guandu_fire\",\"label\":\"手持火把麻油，冒矢石冲入袁军粮囤放火\",\"description\":\"烈焰映红官渡长空，彻底焚毁袁绍十万大军之命脉！\",\"approachTag\":\"【火焚粮仓】\",\"requirementHint\":\"需勇略过人\",\"statChanges\":{\"martial\":14,\"intellect\":6,\"wealth\":12,\"fortune\":6},\"outcomeText\":\"万囤军粮化作滚滚火海！淳于琼溃败，袁军十万大军闻粮尽皆土崩瓦解。曹公亲自抚慰将士，赏帛十匹。\",\"campaignUnlock\":{\"campaignName\":\"官渡之战 · 乌巢奇袭\",\"camp\":\"WEI\",\"commander\":\"曹操\",\"roleTitle\":\"牙门破虏别将\"},\"eventFlagToSet\":\"done:evt_guandu\"},{\"id\":\"c_guandu_guard\",\"label\":\"于大营前沿操作发石霹雳车，轰击袁绍高橹敌楼\",\"description\":\"乱石横空飞渡，以器械之力压制河北弓弩手。\",\"approachTag\":\"【操持重械】\",\"requirementHint\":\"需识见精巧\",\"statChanges\":{\"intellect\":12,\"martial\":6,\"wealth\":6},\"outcomeText\":\"巨石腾空呼啸，将袁军木质敌楼砸得粉碎！前锋士卒士气大振，你被擢升为军械司马。\",\"campaignUnlock\":{\"campaignName\":\"官渡之战 · 乌巢奇袭\",\"camp\":\"WEI\",\"commander\":\"曹操\",\"roleTitle\":\"军械营司马\"},\"eventFlagToSet\":\"done:evt_guandu\"}]', 1),
  ('evt_guandu_200_shu_runan', 'HISTORICAL_CAMPAIGN', 95, '官渡之战 · 汝南策应', 200, 200, '[2,3]', 16, 65, 'SHU', NULL, NULL, '[\"done:evt_guandu\"]', NULL, NULL, '建安五年官渡决战之际，刘玄德引军进驻汝南，联络刘辟、龚都余部，从侧翼袭扰许昌郊野，牵制曹军后路！', '刘备于汝南策应北方，曹仁大军逼近，你当如何行事？', NULL, '[{\"id\":\"c_runan_ambush\",\"label\":\"随赵子龙埋伏于山谷密林，截击曹仁前哨骑兵\",\"description\":\"神出鬼没，袭扰敌军粮草辎重。\",\"approachTag\":\"【密林奇袭】\",\"requirementHint\":\"需敏锐与勇略\",\"statChanges\":{\"martial\":12,\"intellect\":8,\"fortune\":6},\"outcomeText\":\"伏兵四起，曹仁斥候受创撤退。赵云夸你弓马熟练，引荐你为玄德帐前哨官。\",\"campaignUnlock\":{\"campaignName\":\"官渡汝南策应\",\"camp\":\"SHU\",\"commander\":\"赵云\",\"roleTitle\":\"玄德帐前哨探长\"},\"eventFlagToSet\":\"done:evt_guandu\"},{\"id\":\"c_runan_leave_civilian\",\"label\":\"【战乱下野】战局动荡颠沛流离，向刘玄德垂泪请辞还乡务农\",\"description\":\"刘玄德仁厚，赠你三斗大米放你还乡。\",\"approachTag\":\"【辞军为民】\",\"requirementHint\":\"下野还乡\",\"statChanges\":{\"virtue\":10,\"wealth\":4},\"outcomeText\":\"刘备挥泪相送：“百姓艰难，君归乡好生度日。”你脱离军籍，返回老家躬耕。\",\"leaveMilitary\":true,\"eventFlagToSet\":\"done:evt_guandu\"}]', 1),
  ('evt_guandu_200_civilian_grain', 'CIVILIAN_DAILY', 85, NULL, 200, 200, '[2,3]', 12, 75, 'CIVILIAN_ONLY', NULL, NULL, '[\"done:evt_guandu\"]', NULL, NULL, '建安五年秋冬，官渡数十万大军交锋。两军差役四出搜刮，无论曹袁，皆挨家挨户索要军粮壮丁，里邻啼哭震野。', '官渡战云笼罩，差役挨户索粮抓丁，你该如何保全一家口粮？', NULL, '[{\"id\":\"c_civ_hide_grain\",\"label\":\"在屋后枯井深挖暗窖，将麦米埋于地下，仅留秕糠应付搜查\",\"description\":\"斗智斗勇，保护活命口粮。\",\"approachTag\":\"【秘窖藏谷】\",\"requirementHint\":\"需机敏谋略\",\"statChanges\":{\"intellect\":10,\"wealth\":6,\"fortune\":4},\"outcomeText\":\"差役搜走了一袋烂秕糠悻悻离去，一家人靠着窖藏麦粒熬过了大荒之冬。\",\"eventFlagToSet\":\"done:evt_guandu\"},{\"id\":\"c_civ_flee_mountains\",\"label\":\"收拾细软铺盖，举家躲入深山密林结寨自保\",\"description\":\"宁居山林受冻，不逢兵灾乱刃。\",\"approachTag\":\"【隐入深山】\",\"requirementHint\":\"勤劳忍苦\",\"statChanges\":{\"health\":6,\"virtue\":8,\"wealth\":-6},\"outcomeText\":\"在山中搭建草庵采野栗充饥，避开了两军拉夫之祸，全家安好。\",\"eventFlagToSet\":\"done:evt_guandu\"}]', 1),
  ('evt_campaign_208_changbanpo_shu', 'HISTORICAL_CAMPAIGN', 100, '当阳长坂护幼主', 208, 208, '[2]', 16, 65, 'SHU', NULL, NULL, '[\"done:evt_changbanpo\"]', NULL, NULL, '曹操五千精锐纯血虎豹骑日夜兼程追及当阳景山！十万随刘备撤退的荆襄百姓号哭奔逃，赵子龙银枪白马回身杀入重围救护阿斗！', '曹操五千纯血虎豹骑一日一夜疾驰三百里追及！十万襄阳难民号哭奔逃，赵子龙单骑回马破阵救幼主！', NULL, '[{\"id\":\"c_changban_with_zhaoyun\",\"label\":\"跟随赵子龙策马折返重围，死命掩护怀抱阿斗的常山银枪\",\"description\":\"浑身是胆，于曹营百万军中七进七出，不负仁德忠义之名！\",\"approachTag\":\"【死命护幼】\",\"requirementHint\":\"需绝大勇气与体魄\",\"statChanges\":{\"martial\":18,\"virtue\":16,\"health\":-8,\"fortune\":10},\"outcomeText\":\"长矛刺穿数名追兵，你的战袍尽被血浸透！终于掩护子龙冲出景山合围，刘备携你双手洒泪相迎：“真义士也！”\",\"campaignUnlock\":{\"campaignName\":\"当阳长坂护幼主\",\"camp\":\"SHU\",\"commander\":\"赵云\",\"roleTitle\":\"顺平侯贴身校尉\"},\"eventFlagToSet\":\"done:evt_changbanpo\"},{\"id\":\"c_changban_bridge\",\"label\":\"随张飞据水断桥，横矛立马于长坂桥头作怒目金刚吼\",\"description\":\"“身是张翼德也，可来共决死！”拆断木桥阻绝曹军前锋。\",\"approachTag\":\"【据水断桥】\",\"requirementHint\":\"需胆魄非凡\",\"statChanges\":{\"martial\":12,\"intellect\":6,\"virtue\":10},\"outcomeText\":\"桥头巨吼如雷，曹操疑有伏兵按辔不前。趁此间隙，数万残存百姓与将士终于安然退至汉津口登船。\",\"campaignUnlock\":{\"campaignName\":\"当阳长坂护幼主\",\"camp\":\"SHU\",\"commander\":\"张飞\",\"roleTitle\":\"长坂桥卫士长\"},\"eventFlagToSet\":\"done:evt_changbanpo\"}]', 1),
  ('evt_campaign_208_chibi_wei', 'HISTORICAL_CAMPAIGN', 100, '赤壁鏖兵 · 锁江火海', 208, 208, '[3]', 16, 65, 'WEI', NULL, NULL, '[\"done:evt_chibi\"]', NULL, NULL, '建安十三年冬十一月，东南狂风骤起！黄盖引数十艘火船撞入水寨，曹公战船铁索相连难解，瞬息化作一片火海！曹军水寨江水沸腾，全线大溃！', '赤壁烈焰冲天，铁索连环战船尽陷火海，吴军火箭如雨，你当如何突围？', NULL, '[{\"id\":\"c_chibi_wei_cut_chains\",\"label\":\"【冒火斩索】手持巨斧冒着箭雨冲上船头劈砍铁索，抢救后营战船\",\"description\":\"极度凶险，若体魄与勇略不济，恐当场葬身滔天烈火！\",\"approachTag\":\"【火海死拼】\",\"requirementHint\":\"需极高体魄与勇略\",\"statChanges\":{\"martial\":16,\"virtue\":8,\"health\":-14},\"outcomeText\":\"你劈断两根铁索，救下两艘中型战船，护送中军突围南撤！曹公亲自赐你青釭佩剑以嘉其勇。\",\"campaignUnlock\":{\"campaignName\":\"赤壁突围死士\",\"camp\":\"WEI\",\"commander\":\"曹操\",\"roleTitle\":\"破火先锋校尉\"},\"eventFlagToSet\":\"done:evt_chibi\"},{\"id\":\"c_chibi_wei_jump_water\",\"label\":\"【弃船泅渡】弃船跳入冰冷江水，泅渡至南岸，护卫曹公败走华容道\",\"description\":\"江水冰刺刺骨，避开烈火直奔南岸陆路。\",\"approachTag\":\"【泅渡突围】\",\"requirementHint\":\"通晓水性，坚韧耐寒\",\"statChanges\":{\"health\":-8,\"intellect\":8,\"fortune\":6},\"outcomeText\":\"你在严冬刺骨的江水中拼力泅水登岸，跟随曹公冒大雨穿过泥泞华容道脱险还北！\",\"eventFlagToSet\":\"done:evt_chibi\"},{\"id\":\"c_chibi_wei_captured\",\"label\":\"【战乱被俘】泅水不及被东吴巡逻艨艟用铁钩锁拿，成为吴军俘虏\",\"description\":\"落入东吴水军之手，面临命运转折。\",\"approachTag\":\"【兵败被俘】\",\"requirementHint\":\"生死抉择\",\"statChanges\":{\"health\":-6,\"fortune\":-4},\"outcomeText\":\"吴军将你捞上战船押解至柴桑大营！\",\"followUpChoice\":{\"prompt\":\"周郎中军大帐点验俘虏，令曹军降者不杀。你作何抉择？\",\"options\":[{\"id\":\"c_chibi_cap_join_wu\",\"label\":\"【归降东吴】愿投吴大帝孙权水师效力\",\"description\":\"换上吴军战袍，成为江东水师一员。\",\"approachTag\":\"【降吴效命】\",\"requirementHint\":\"阵营转为东吴\",\"statChanges\":{\"intellect\":8,\"wealth\":6,\"virtue\":-4},\"outcomeText\":\"周瑜赏识你通晓北方战阵，留任水寨操练降兵，自此改属东吴！\",\"campaignUnlock\":{\"campaignName\":\"赤壁归降东吴\",\"camp\":\"WU\",\"commander\":\"周瑜\",\"roleTitle\":\"江东水师降阵牙将\"},\"eventFlagToSet\":\"done:evt_chibi\"},{\"id\":\"c_chibi_cap_leave\",\"label\":\"【下野还乡】谎称荆州强征平民，求周郎放还故里\",\"description\":\"从此解甲归田，不再涉足兵戈。\",\"approachTag\":\"【下野为民】\",\"requirementHint\":\"脱离军伍\",\"statChanges\":{\"virtue\":6,\"wealth\":-4,\"fortune\":8},\"outcomeText\":\"吴军核实你为苦役，发还路引。你千恩万谢渡江北返，回乡做个踏实农夫。\",\"leaveMilitary\":true,\"eventFlagToSet\":\"done:evt_chibi\"},{\"id\":\"c_chibi_cap_die\",\"label\":\"【宁死不降】挺胸怒斥碧眼儿孙权背叛朝廷\",\"description\":\"尽显忠节，舍身成仁。\",\"approachTag\":\"【慷慨取义】\",\"requirementHint\":\"忠烈就义\",\"statChanges\":{\"virtue\":20},\"outcomeText\":\"周瑜感叹其忠勇，斩首厚葬。\",\"isDirectFatal\":true,\"fatalDeathReason\":\"赤壁战败被俘后宁死不从东吴，慷慨就义于江畔。\"}]}}]', 1),
  ('evt_campaign_208_chibi_wu', 'HISTORICAL_CAMPAIGN', 100, '赤壁鏖兵火烧连环', 208, 208, '[3]', 16, 65, 'WU', NULL, NULL, '[\"done:evt_chibi\"]', NULL, NULL, '冬十一月，东南风狂啸！黄盖引二十艘蒙冲斗舰，满载芦苇油脂突入曹军水寨，大呼“降曹”，烈焰顺风腾空八百里，江水尽赤！', '东南风骤起！黄盖引二十艘蒙冲快船满载干柴鱼膏疾驰曹军水寨，烈焰腾空！', NULL, '[{\"id\":\"c_chibi_wu_fire_ship\",\"label\":\"跃上满载油脂干苇的蒙冲快船，引火撞击曹营锁江巨舰\",\"description\":\"乘东南狂风突进，烈焰横江八百里，樯橹灰飞烟灭！\",\"approachTag\":\"【烈火冲阵】\",\"requirementHint\":\"需通晓水性或勇略\",\"statChanges\":{\"martial\":16,\"virtue\":8,\"wealth\":10,\"fortune\":8},\"outcomeText\":\"赤壁烈焰冲天，大火连延曹军水旱双营，江水尽赤！周郎引数万精锐大破敌阵，天下三分自此底定。\",\"campaignUnlock\":{\"campaignName\":\"赤壁鏖兵火烧连环\",\"camp\":\"WU\",\"commander\":\"周瑜\",\"roleTitle\":\"破曹水师牙门将\"},\"eventFlagToSet\":\"done:evt_chibi\"}]', 1),
  ('evt_campaign_208_chibi_civilian', 'CIVILIAN_DAILY', 85, NULL, 208, 208, '[2,3]', 12, 75, 'CIVILIAN_ONLY', NULL, NULL, '[\"done:evt_chibi\"]', NULL, NULL, '建安十三年曹公大军南下荆襄，水陆数十万兵马扎营赤壁。江上战火将天空烧得通红，两岸渔民与流民四散避匿。', '江汉战事汹涌，大火照彻百里，你作何避难决断？', NULL, '[{\"id\":\"c_chibi_civ_boat_save\",\"label\":\"摇动乌篷小舟，在江汉浅滩搭救落水百姓与伤兵\",\"description\":\"慈悲为怀，广积阴德。\",\"approachTag\":\"【慈航救生】\",\"requirementHint\":\"需仁厚仁义\",\"statChanges\":{\"virtue\":18,\"intellect\":8,\"fortune\":10},\"outcomeText\":\"你在浓烟中捞救了二十余口落水妇孺，两岸乡党尊称你为江上活佛。\",\"eventFlagToSet\":\"done:evt_chibi\"},{\"id\":\"c_chibi_civ_stay_hills\",\"label\":\"藏身云梦泽深处芦苇荡，静待天下大势平息\",\"description\":\"不问兵戈，但求阖家安康。\",\"approachTag\":\"【隐匿湖泽】\",\"requirementHint\":\"安分守常\",\"statChanges\":{\"health\":6,\"wealth\":6,\"fortune\":6},\"outcomeText\":\"春暖花开，曹操北撤，你在湖边修补茅屋，日子重归平静。\",\"eventFlagToSet\":\"done:evt_chibi\"}]', 1),
  ('evt_crisis_217_epidemic', 'CRISIS_ORDEAL', 95, NULL, 217, 217, '[3]', 12, 75, NULL, NULL, NULL, '[\"done:evt_217_epidemic\"]', NULL, NULL, '建安二十二年严冬，中原暴发空前伤寒大疫，家家有僵尸之痛，室室有号泣之哀！建安七子中四人同卒于疫。全家高热战栗，危在旦夕！', '伤寒恶疾袭来，全家高热战栗，你该如何救全家人性命？', NULL, '[{\"id\":\"c_age33_soup\",\"label\":\"遵南阳张仲景医书所传“当归生姜羊肉汤 / 麻黄汤”熬煮浓汁痛饮\",\"description\":\"信名医方剂，重姜葱发汗退热，不事巫鬼。\",\"approachTag\":\"【按方发汗】\",\"requirementHint\":\"需识见明辨\",\"statChanges\":{\"health\":12,\"intellect\":8,\"wealth\":-6},\"outcomeText\":\"一碗浓汤灌下，通体大汗淋漓！次日热退骨安，你还将此法传授给隔壁邻舍，活人无数。\",\"eventFlagToSet\":\"done:evt_217_epidemic\"},{\"id\":\"c_age33_quarantine\",\"label\":\"闭门绝客，庭院遍洒生石灰，燃艾草熏蒸屋角\",\"description\":\"坚决执行严苛隔离之策，耐心挨过冬寒疫期。\",\"approachTag\":\"【严密隔离】\",\"requirementHint\":\"坚忍克制，谨守门房\",\"statChanges\":{\"health\":8,\"wealth\":-4},\"outcomeText\":\"虽然家中存粮耗损大半，但一家老小无一人病殁，安然熬过了这场建安大劫。\",\"eventFlagToSet\":\"done:evt_217_epidemic\"},{\"id\":\"c_age33_pray\",\"label\":\"随众去道观求取黄纸符水焚化吞服祈福\",\"description\":\"求神问卜，听天由命。\",\"approachTag\":\"【迷信符水】\",\"requirementHint\":\"吉凶难卜，易误病机\",\"statChanges\":{\"health\":-14,\"fortune\":-4},\"outcomeText\":\"符水无济于事，你连烧了二十日，险些一命呜呼，病愈后落下了肺经喘咳之疾。\",\"eventFlagToSet\":\"done:evt_217_epidemic\"}]', 1),
  ('evt_campaign_219_fancheng_shu', 'HISTORICAL_CAMPAIGN', 100, '襄樊鏖兵 · 水淹七军', 219, 219, '[2,3]', 16, 65, 'SHU', NULL, NULL, '[\"done:evt_fancheng\"]', NULL, NULL, '秋八月霖雨连绵，汉水暴涨五丈！关羽乘大船浮水攻樊城，于禁七军三万人尽皆沉溺投降，威震华夏！然而冬十月吕蒙白衣渡江偷袭荆州，后路断绝，大军退守麦城！', '汉水滔天淹七军，后方江陵却遭吕蒙袭破！四面楚歌之际，你当如何决断？', NULL, '[{\"id\":\"c_fancheng_maicheng_breakout\",\"label\":\"【死战麦城】随关君侯与关平突围决死，阻截吴军层层绊马索与伏兵\",\"description\":\"面对数万吴军合围，拼死护卫君侯！若勇力不足恐力竭殉节。\",\"approachTag\":\"【义薄云天】\",\"requirementHint\":\"需绝大勇略与忠诚\",\"statChanges\":{\"martial\":16,\"virtue\":18,\"health\":-15},\"outcomeText\":\"临沮小道伏兵尽起，你挺枪搏杀数人掩护君侯突围，身中三矢负创坠马，被益州山民冒死救入深山。\",\"campaignUnlock\":{\"campaignName\":\"麦城死战突围\",\"camp\":\"SHU\",\"commander\":\"关羽\",\"roleTitle\":\"忠勇先锋牙门校尉\"},\"eventFlagToSet\":\"done:evt_fancheng\"},{\"id\":\"c_fancheng_escape_sichuan\",\"label\":\"【潜入西川】抄小道翻越崇山峻岭，跋涉千里逃往西川成都报信\",\"description\":\"避开吴军盘查，为先主刘备带回荆州前线机密军情。\",\"approachTag\":\"【翻山还蜀】\",\"requirementHint\":\"需识见机敏与坚毅\",\"statChanges\":{\"intellect\":12,\"health\":-6,\"virtue\":8},\"outcomeText\":\"你历经千难万险翻越巴山蜀水抵达成都，先主刘备痛哭抚你背脊，拔擢你为禁军卫尉。\",\"campaignUnlock\":{\"campaignName\":\"襄樊突围还蜀\",\"camp\":\"SHU\",\"commander\":\"刘备\",\"roleTitle\":\"成都宿卫牙门校尉\"},\"eventFlagToSet\":\"done:evt_fancheng\"},{\"id\":\"c_fancheng_leave_civilian\",\"label\":\"【下野避难】战局崩裂荆州异主，脱下铠甲隐入汉水民舍务农\",\"description\":\"远离蜀吴争斗旋涡，做个本分乡民。\",\"approachTag\":\"【藏身草莽】\",\"requirementHint\":\"脱离军伍\",\"statChanges\":{\"virtue\":6,\"wealth\":-4,\"fortune\":6},\"outcomeText\":\"你将兵刃埋于竹林，重做布衣耕汉水肥田，安然度过荆州易主之劫。\",\"leaveMilitary\":true,\"eventFlagToSet\":\"done:evt_fancheng\"}]', 1),
  ('evt_campaign_219_fancheng_civilian', 'CIVILIAN_DAILY', 85, NULL, 219, 219, '[2,3]', 12, 75, 'CIVILIAN_ONLY', NULL, NULL, '[\"done:evt_fancheng\"]', NULL, NULL, '建安二十四年秋，襄樊大水漫灌城墙，平地积水数丈，沿江庄稼瓦舍漂没无数，关羽与曹军在水中激战，百姓流离失所。', '大水浸漫屋舍，大批淹死人畜漂过，你如何带领家人度过洪荒？', NULL, '[{\"id\":\"c_flood_raft\",\"label\":\"连夜扎结木筏高搭窝棚，划水捞救浮木与落水邻舍\",\"description\":\"互助共济，熬过水灾。\",\"approachTag\":\"【扎筏救民】\",\"requirementHint\":\"需仁厚仁义\",\"statChanges\":{\"virtue\":16,\"health\":4,\"wealth\":-4},\"outcomeText\":\"全村靠你的大木筏保全了二十余户性命，水退后乡邻合力替你重修房舍。\",\"eventFlagToSet\":\"done:evt_fancheng\"},{\"id\":\"c_flood_high_ground\",\"label\":\"背负存粮举家逃往荆山高岗，避开下流瘟疫与乱兵\",\"description\":\"登高避水，防范时疫。\",\"approachTag\":\"【登高远避】\",\"requirementHint\":\"机敏谨慎\",\"statChanges\":{\"health\":6,\"intellect\":8,\"fortune\":6},\"outcomeText\":\"你在高山干燥处度过灾期，无一人受湿热恶疾感染，秋后重返田舍。\",\"eventFlagToSet\":\"done:evt_fancheng\"}]', 1),
  ('evt_campaign_228_qishan_shu', 'HISTORICAL_CAMPAIGN', 100, '武乡侯一出祁山', 228, 228, '[0]', 16, 65, 'SHU', NULL, NULL, '[\"done:evt_qishan\"]', NULL, NULL, '建兴六年春，诸葛丞相上一出师表，率三军出祁山，天水三郡震动降蜀！张郃引魏军精骑直扑要道街亭，马谡违规舍水扎营于孤山，胜负系于一线！', '街亭前线，马谡欲舍水上山扎营，张郃大军转瞬即至，你当如何行事？', NULL, '[{\"id\":\"c_qishan_guard_pass\",\"label\":\"【随王平据道】随裨将军王平坚守山下当道筑垒，死守水源防线\",\"description\":\"力遵丞相方略，严防魏军切断汲水道。\",\"approachTag\":\"【死守要冲】\",\"requirementHint\":\"需识见沉稳与武略\",\"statChanges\":{\"martial\":14,\"intellect\":10,\"fortune\":8},\"outcomeText\":\"张郃四面围山放火，马谡大溃！唯你随王平鸣钲勒兵拒守，徐徐整队击退追兵，保全大队退回汉中，丞相特嘉奖升赏！\",\"campaignUnlock\":{\"campaignName\":\"街亭断后立功\",\"camp\":\"SHU\",\"commander\":\"诸葛亮\",\"roleTitle\":\"汉中统军牙门正将\"},\"eventFlagToSet\":\"done:evt_qishan\"},{\"id\":\"c_qishan_transport\",\"label\":\"【督运粮草】在险峻秦岭栈道督运粮秣，协助迁移天水千户百姓入蜀\",\"description\":\"运送三军命脉，接济北伐军民。\",\"approachTag\":\"【秦岭督粮】\",\"requirementHint\":\"任劳任怨，善抚百姓\",\"statChanges\":{\"health\":6,\"virtue\":12,\"intellect\":8,\"wealth\":6},\"outcomeText\":\"你冒雨运送数千石麦米，妥善安顿天水迁蜀千余户百姓，丞相亲赐锦袍以旌其劳。\",\"campaignUnlock\":{\"campaignName\":\"祁山督粮安民\",\"camp\":\"SHU\",\"commander\":\"诸葛亮\",\"roleTitle\":\"丞相府督粮从事\"},\"eventFlagToSet\":\"done:evt_qishan\"}]', 1),
  ('evt_campaign_228_qishan_civilian', 'CIVILIAN_DAILY', 85, NULL, 228, 228, '[0]', 12, 75, 'CIVILIAN_ONLY', NULL, NULL, '[\"done:evt_qishan\"]', NULL, NULL, '建兴六年春诸葛亮收拔天水三郡，后因街亭失利，丞相下令拔西县千余家百姓迁居汉中盆地。四野百姓收拾锅碗推车南渡栈道。', '蜀军护送百姓南迁汉中，路途险峻但免于曹魏战后报复，你作何决断？', NULL, '[{\"id\":\"c_qishan_civ_migrate\",\"label\":\"跟随大队官兵南迁汉中天府，分领熟田瓦舍耕种\",\"description\":\"前往安宁少战的蜀中立业。\",\"approachTag\":\"【南迁安家】\",\"requirementHint\":\"搬迁立业\",\"statChanges\":{\"wealth\":8,\"virtue\":8,\"fortune\":6},\"outcomeText\":\"官府在汉中平原为你拨付良田三十亩与耕牛一头，全家在益州安稳扎下根来。\",\"eventFlagToSet\":\"done:evt_qishan\"},{\"id\":\"c_qishan_civ_stay\",\"label\":\"故土难离，留守陇右老宅修复麦田\",\"description\":\"守望桑梓，不离家山。\",\"approachTag\":\"【守望故土】\",\"requirementHint\":\"安土重迁\",\"statChanges\":{\"health\":6,\"wealth\":4},\"outcomeText\":\"战事暂歇，魏军重新进驻，你在旧田上继续春耕劳作。\",\"eventFlagToSet\":\"done:evt_qishan\"}]', 1),
  ('evt_mature_45_elder', 'MATURE_SENIOR', 85, NULL, 229, 235, '[2]', 45, 50, NULL, NULL, NULL, '[\"done:evt_mature_45\"]', NULL, NULL, '步入知命之年。三国各自立国，烽烟稍敛。你的双鬓渐染秋霜，儿女业已成人，乡邻遇事常来听取你的主见。', '步入知命之年，你打算如何安顿往后春秋？', NULL, '[{\"id\":\"c_age45_elder\",\"label\":\"出任乡党三老，秉公主持乡饮与调息邻里争端\",\"description\":\"立德行仁，成为地方受人敬重的大长辈。\",\"approachTag\":\"【乡党宗长】\",\"requirementHint\":\"崇德厚望，泽被桑梓\",\"statChanges\":{\"virtue\":14,\"intellect\":6,\"wealth\":4},\"outcomeText\":\"县长巡行过村亦下车揖手相问，邻里田宅口角只要你一言便冰释前嫌，威望日隆。\",\"eventFlagToSet\":\"done:evt_mature_45\"},{\"id\":\"c_age45_farm_expand\",\"label\":\"督导子孙辛勤整修水田，建起榨油碾米水磨坊\",\"description\":\"为子孙打下扎实家私产业，家道殷实。\",\"approachTag\":\"【厚殖家业】\",\"requirementHint\":\"子孙守业，仓廪殷实\",\"statChanges\":{\"wealth\":18,\"health\":4},\"outcomeText\":\"家中谷满仓、猪羊满圈。在数十载离乱沧桑之后，你守护住了一大家子的安稳烟火。\",\"eventFlagToSet\":\"done:evt_mature_45\"},{\"id\":\"c_age45_music\",\"label\":\"手刻竹笛短箫，常在老槐树下为村童吹奏汉末民谣\",\"description\":\"浮名利禄皆浮云，寄情山水乐道知命。\",\"approachTag\":\"【寄情山野】\",\"requirementHint\":\"淡泊明志，宁静致远\",\"statChanges\":{\"virtue\":10,\"health\":8,\"fortune\":6},\"outcomeText\":\"夕阳斜照，箫声悠扬穿过田野，孩子们拍手欢唱，你心中一片宁静淡泊。\",\"eventFlagToSet\":\"done:evt_mature_45\"}]', 1),
  ('evt_senior_60_retrospective', 'MATURE_SENIOR', 85, NULL, 244, 255, '[3]', 60, 65, NULL, NULL, NULL, '[\"done:evt_senior_60\"]', NULL, NULL, '年逾花甲，寒冬初雪。三国的枭雄老将皆已作古，你坐在柴火盆旁烤红薯，膝下孙儿拉着你的衣襟，问起当年赤壁与官渡的烽火。', '孙儿仰着稚嫩的小脸问：“爷爷，当年那些大英雄大人物到底争的是什么呀？”', NULL, '[{\"id\":\"c_age60_ordinary\",\"label\":\"“什么开疆拓土，都比不上一锅热饭、一家齐整。”\",\"description\":\"看透了霸业功名背后的森森白骨，深知平淡之珍贵。\",\"approachTag\":\"【大智若愚】\",\"requirementHint\":\"返璞归真，了悟浮生\",\"statChanges\":{\"virtue\":12,\"intellect\":8},\"outcomeText\":\"孙儿似懂非懂地咬着红薯重重点头。那一晚，你睡得格外平静香甜。\",\"eventFlagToSet\":\"done:evt_senior_60\"},{\"id\":\"c_age60_record\",\"label\":\"取出珍藏多年的粗麻纸，就着油灯把六十年真实见闻口述记为家谱\",\"description\":\"以一个平凡生灵的双眼，留存这大乱甲子最真实的血泪印记。\",\"approachTag\":\"【笔录沧桑】\",\"requirementHint\":\"文心传世，青史留存\",\"statChanges\":{\"intellect\":14,\"virtue\":8},\"outcomeText\":\"这卷写在粗纸上的草民笔记，后来成为后世史官考求汉末民间世相最弥足珍贵的文献。\",\"eventFlagToSet\":\"done:evt_senior_60\"}]', 1)
